"use strict";function attachWebSocketErrorLogging(socket,stream,logger){let reported=false;const report=error=>{if(reported)return;reported=true;logger.error("MQTT WebSocket error:",{code:error&&error.code?error.code:null,message:error&&error.message?error.message:String(error||"Unknown WebSocket error")});if(stream&&!stream.destroyed)stream.destroy(error instanceof Error?error:new Error(String(error)))};const onUnexpectedResponse=(_request,response)=>{const error=new Error(`Unexpected WebSocket response: HTTP ${response.statusCode}`);error.code=`HTTP_${response.statusCode}`;report(error);response.resume()};socket.once("error",report);socket.once("unexpected-response",onUnexpectedResponse);return()=>{socket.removeListener("error",report);socket.removeListener("unexpected-response",onUnexpectedResponse)}}module.exports={attachWebSocketErrorLogging:attachWebSocketErrorLogging};
